const cfg=window.STUDENT_COMPETENCE_CONFIG;
const levels={
  oge_17_1_1:2,oge_17_1_2:2,oge_17_1_3:2,oge_17_1_4:2,
  oge_17_3_1:2,oge_17_3_3:2,
  oge_23_3_1:2,oge_23_3_2:2,oge_23_3_3:2,oge_23_3_4:2,
  oge_24_3_1:2,oge_24_3_2:2,oge_24_3_3:2,oge_24_3_4:2,
  oge_25_2_1:2,oge_25_2_2:2,oge_25_2_5:1
};
const evidence={
  oge_17_1_1:{text:'Занятие 04.09: свойства ромба использованы при поиске расстояния от центра до стороны и выборе высоты.',href:'04.09.26.html'},
  oge_17_1_2:{text:'Занятие 04.09: повторены свойства диагоналей ромба — перпендикулярность, деление пополам и деление углов пополам.',href:'04.09.26.html'},
  oge_17_1_3:{text:'Занятие 04.09: длины в ромбе связывались через прямоугольный треугольник, синус, косинус и высоту.',href:'04.09.26.html'},
  oge_17_1_4:{text:'Занятие 04.09: площадь ромба вычислялась по формуле S=a²·sin α и через основание с высотой.',href:'04.09.26.html'},
  oge_17_3_1:{text:'Занятие 04.09: свойства параллелограмма использованы для получения равных углов и равных противоположных сторон.',href:'04.09.26.html'},
  oge_17_3_3:{text:'Занятие 04.09: биссектрисы, параллельные стороны и подобные треугольники использованы для поиска длин и отношений.',href:'04.09.26.html'},
  oge_23_3_1:{text:'Занятие 04.09: отрабатывался структурный анализ сложной конфигурации с квадратом, параллелограммом и ромбом.',href:'04.09.26.html'},
  oge_23_3_2:{text:'Занятие 04.09: выбор между подобием, тригонометрией, Пифагором и площадями выполнялся по признакам чертежа.',href:'04.09.26.html'},
  oge_23_3_3:{text:'Занятие 04.09: построены цепочки вычислений через равные углы, сходственные стороны, высоту и площадь.',href:'04.09.26.html'},
  oge_23_3_4:{text:'Занятие 04.09: ответы проверялись по исходным длинам, взаимному расположению и свойствам фигуры.',href:'04.09.26.html'},
  oge_24_3_1:{text:'Занятие 04.09: формулировалась цель доказательства через равенство углов, отрезков и параллельность.',href:'04.09.26.html'},
  oge_24_3_2:{text:'Занятие 04.09: ключевыми признаками были подобие по двум углам и равнобедренность через биссектрису и параллельность.',href:'04.09.26.html'},
  oge_24_3_3:{text:'Занятие 04.09: обсуждались дополнительные перпендикуляры и вспомогательные точки как осмысленные построения.',href:'04.09.26.html'},
  oge_24_3_4:{text:'Занятие 04.09: акцент сделан на полной записи причин равенства углов и соответствия сторон.',href:'04.09.26.html'},
  oge_25_2_1:{text:'Занятие 04.09: поиск скрытых прямоугольных и подобных треугольников использован как основной структурный приём.',href:'04.09.26.html'},
  oge_25_2_2:{text:'Занятие 04.09: метрические соотношения строились через высоты, биссектрисы, тригонометрию и пропорции.',href:'04.09.26.html'},
  oge_25_2_5:{text:'Занятие 04.09: начата практика комбинированного выбора метода в сложных задачах на четырёхугольники.',href:'04.09.26.html'}
};
if(cfg){
  cfg.teacherSeed=Object.assign({},cfg.teacherSeed||{},levels);
  cfg.evidence=Object.assign({},cfg.evidence||{},evidence);
}
try{
  const key=(cfg&&cfg.stateKey)||'sofya-competence-state-v2';
  const raw=localStorage.getItem(key);
  if(raw){
    const state=JSON.parse(raw);
    if(state&&state.schemaVersion===2&&state.studentLevels&&typeof state.studentLevels==='object'){
      let changed=false;
      for(const [id,level] of Object.entries(levels)){
        const current=Number(state.studentLevels[id]??0);
        if(current<level){state.studentLevels[id]=level;changed=true;}
      }
      if(changed){state.updatedAt=new Date().toISOString();localStorage.setItem(key,JSON.stringify(state));}
    }
  }
}catch(_){}
